import re


def normalize_phone(raw):
    text = re.sub(r"[ .\-()]", "", raw)
    if text.startswith("+"):
        text = text[1:]
    if not re.fullmatch(r"1?[0-9]{10}", text):
        raise ValueError("not a US phone number: %r" % raw)
    return "+1" + text[-10:]

_STRIP = str.maketrans("", "", " .-()")


def _is_ascii_digits(s):
    return len(s) > 0 and all("0" <= c <= "9" for c in s)


def normalize_phone(raw):
    cleaned = raw.translate(_STRIP)
    if cleaned[:1] == "+":
        cleaned = cleaned[1:]
    if not _is_ascii_digits(cleaned):
        raise ValueError("invalid phone: %r" % (raw,))
    if len(cleaned) == 11 and cleaned[0] == "1":
        national = cleaned[1:]
    elif len(cleaned) == 10:
        national = cleaned
    else:
        raise ValueError("invalid phone: %r" % (raw,))
    return "+1" + national

