def future_value(principal, annual_rate, years, periods_per_year):
    rate = annual_rate / 100.0
    n = periods_per_year
    value = principal * (1 + rate / n) ** years
    return round(value, 2)

def future_value(principal, annual_rate, years, periods_per_year):
    rate = annual_rate
    n = periods_per_year
    value = principal * (1 + rate / n) ** (n * years)
    return round(value, 2)

def future_value(principal, annual_rate, years, periods_per_year):
    periods = periods_per_year
    per_period_rate = (annual_rate / 100.0) / periods
    growth = pow(1 + per_period_rate, periods * years)
    return round(float(principal * growth), 2)
